// 위대한 기업 개별 심층 분석 — 인사이트의 1~5번 섹션 안에 들어간다.
// 숫자: SEC 공시 EPS·잉여현금흐름(fundamentals JSON), 주가는 Yahoo. 최근 상황은 각 회사 실적 발표·보도로 확인(작성일 기준).
//   now      → 1번 '지금 한눈에': 지금 무슨 일이 있나
//   drivers  → 4번 '앞으로': 이익을 움직일 요인
//   growth   → 판단한 앞으로 10년 EPS 연 성장률(중심·범위). 2번 이익 시계 성장률 바의 기본값과 '개별 분석 판단' 눈금이 된다
//   verdict, watch → 5번 결론
// 작성 순서: 빅테크 → 버핏 관련 → 나머지 위대한 기업 (묶음별로 추가)

export type DeepInsight = {
  asOf: string
  headline: string
  // 무슨 회사인가: what = 한 문장 설명, money = 돈을 어떻게 버나
  biz?: { what: string; money: string }
  // 해자 점검: state = 그대로 / 약해지는 중 / 흔들림, sources = 해자의 근거, threats = 위협, why = 판정 이유
  moat?: { state: 'intact' | 'weakening' | 'broken'; sources: string[]; threats: string[]; why: string }
  now: string[]
  drivers: { k: string; v: string }[]
  growth: { base: number; lo: number; hi: number; why: string }
  verdict: string[]
  watch: string[]
}

